const path = require('path');
const dotenv = require('dotenv');
const TelegramBot = require('node-telegram-bot-api');
const { logInfo, logWarning, logError } = require('./utils/logger');
const handleCmd = require('./commands/cmd');
const handleNew = require('./commands/new');
const handlePing = require('./commands/ping');

dotenv.config();

const token = process.env.TELEGRAM_BOT_TOKEN;
const allowedIds = (process.env.ALLOWED_CHAT_ID || '').split(',').map((id) => id.trim()).filter(Boolean);
const openEditorCommand = process.env.OPEN_EDITOR_COMMAND || 'code';

if (!token) {
  logError('TELEGRAM_BOT_TOKEN is required in .env');
  process.exit(1);
}

if (!allowedIds.length) {
  logWarning('ALLOWED_CHAT_ID is not configured. /cmd and /new will be disabled until it is set.');
}

const bot = new TelegramBot(token, { polling: true });

bot.on('polling_error', (error) => {
  logError('Polling error: ' + error.message);
});

bot.onText(/\/ping\b/, async (msg) => {
  await handlePing(bot, msg, logInfo);
});

bot.onText(/\/cmd(?:\s+([\s\S]+))?/, async (msg, match) => {
  try {
    await handleCmd(bot, msg, match ? match[1] : '', allowedIds, logInfo);
  } catch (error) {
    await bot.sendMessage(msg.chat.id, `Error executing command: ${error.message}`);
    logError(error.message);
  }
});

bot.onText(/\/new(?:\s+([\s\S]+))?/, async (msg, match) => {
  try {
    await handleNew(bot, msg, match ? match[1] : '', allowedIds, openEditorCommand, logInfo);
  } catch (error) {
    await bot.sendMessage(msg.chat.id, `Error creating file: ${error.message}`);
    logError(error.message);
  }
});

bot.on('message', (msg) => {
  const text = msg.text || '';
  if (!text.startsWith('/')) {
    return;
  }

  if (!/\/(ping|cmd|new)\b/.test(text)) {
    bot.sendMessage(msg.chat.id, 'Command not recognized. Use /ping, /cmd, or /new.');
  }
});

process.on('unhandledRejection', (error) => {
  logError('Unhandled rejection: ' + String(error));
});

process.on('uncaughtException', (error) => {
  logError('Uncaught exception: ' + String(error));
});

logInfo('Telegram coding assistant started. Waiting for messages...');
